1	/**
2	 * LanChat 前端交互逻辑。
3	 *
4	 * 全局状态:
5	 *   myInfo       - 本机信息 {uuid, name, ip, network, ws_port}
6	 *   onlinePeers  - 在线节点 Map<uuid, {name, ip}>
7	 *   contacts     - 历史联系人 Map<uuid, {name, ip, status, messages[]}>
8	 *   pendingReqs  - 待处理连接请求 Map<uuid, {name}>
9	 *   activeChats  - 活跃聊天 WS Map<uuid, WebSocket>
10	 *   currentChat  - 当前显示的聊天 uuid | null
11	 *   pendingMsgs  - 待确认消息 Map<msg_id, {content, uuid, timestamp}>
12	 *   pendingFileTransfers - 待处理的文件上传 {transferId: {file, uuid, ...}}
13	 */
14	
15	// ===== 全局状态 =====
16	let myInfo = null;
17	let onlinePeers = new Map();
18	let contacts = new Map();
19	let pendingRequests = new Map();
20	let activeChats = new Map();         // uuid → WebSocket（主动发起方有值）
21	let connectedPeers = new Set();      // 连接已确认的 peer uuid（双方向都追踪，含接收方）
22	let currentChat = null;
23	let pendingMessages = new Map();
24	let controlWs = null;
25	let reconnectTimer = null;
26	let reconnectAttempts = 0;
27	
28	// ===== sessionStorage：刷新后记住连接状态 =====
29	const SS_PREFIX = 'lanchat_conn_';
30	
31	function markConnected(uuid) {
32	    try { sessionStorage.setItem(SS_PREFIX + uuid, '1'); } catch (e) { /* ignore */ }
33	}
34	
35	function markDisconnected(uuid) {
36	    try { sessionStorage.removeItem(SS_PREFIX + uuid); } catch (e) { /* ignore */ }
37	}
38	
39	function getStoredConnectedPeers() {
40	    const peers = [];
41	    try {
42	        for (let i = 0; i < sessionStorage.length; i++) {
43	            const key = sessionStorage.key(i);
44	            if (key && key.startsWith(SS_PREFIX)) {
45	                peers.push(key.slice(SS_PREFIX.length));
46	            }
47	        }
48	    } catch (e) { /* ignore */ }
49	    return peers;
50	}
51	
52	// 文件传输状态
53	let pendingFileTransfers = {};
54	
55	// ===== DOM 引用 =====
56	const $ = (id) => document.getElementById(id);
57	const onlineList = $('online-list');
58	const onlineCount = $('online-count');
59	const pendingList = $('pending-list');
60	const pendingCount = $('pending-count');
61	const panelPending = $('panel-pending');
62	const contactsList = $('contacts-list');
63	const contactsCount = $('contacts-count');
64	const chatPlaceholder = $('chat-placeholder');
65	const chatContainer = $('chat-container');
66	const chatPeerName = $('chat-peer-name');
67	const chatPeerStatus = $('chat-peer-status');
68	const chatConnectBar = $('chat-connect-bar');
69	const btnChatConnect = $('btn-chat-connect');
70	const chatMessages = $('chat-messages');
71	const msgInput = $('msg-input');
72	const btnSend = $('btn-send');
73	const btnSendFile = $('btn-send-file');
74	const fileInput = $('file-input');
75	const btnCloseChat = $('btn-close-chat');
76	const btnDeleteContact = $('btn-delete-contact');
77	const btnDisconnect = $('btn-disconnect');
78	const btnScan = $('btn-scan');
79	const btnEditName = $('btn-edit-name');
80	const modalOverlay = $('modal-overlay');
81	const modalNameInput = $('modal-name-input');
82	const fileModalOverlay = $('file-modal-overlay');
83	const fileModalTitle = $('file-modal-title');
84	const fileModalBody = $('file-modal-body');
85	const fileModalButtons = $('file-modal-buttons');
86	
87	// ===== 初始化 =====
88	async function init() {
89	    await connectControl();
90	    bindEvents();
91	    startPolling();
92	}
93	
94	/** 连接控制 WebSocket */
95	async function connectControl() {
96	    const protocol = location.protocol === 'https:' ? 'wss:' : 'ws:';
97	    const url = `${protocol}//${location.host}/ws/control`;
98	
99	    return new Promise((resolve) => {
100	        controlWs = new WebSocket(url);
101	
102	        controlWs.onopen = () => {
103	            reconnectAttempts = 0;
104	            console.log('[Control] 已连接');
105	        };
106	
107	        controlWs.onmessage = (e) => {
108	            const msg = JSON.parse(e.data);
109	            handleControlMessage(msg);
110	            if (msg.type === 'init') resolve();
111	        };
112	
113	        controlWs.onclose = () => {
114	            console.log('[Control] 断开，尝试重连...');
115	            scheduleReconnect();
116	        };
117	
118	        controlWs.onerror = () => {};
119	    });
120	}
121	
122	/** 控制 WS 断开后指数退避重连 */
123	function scheduleReconnect() {
124	    if (reconnectTimer) return;
125	    const delay = Math.min(1000 * Math.pow(2, reconnectAttempts), 30000);
126	    const jitter = delay * (0.8 + Math.random() * 0.4);
127	    reconnectAttempts++;
128	    reconnectTimer = setTimeout(async () => {
129	        reconnectTimer = null;
130	        await connectControl();
131	    }, jitter);
132	}
133	
134	// ===== 事件绑定 =====
135	function bindEvents() {
136	    btnScan.addEventListener('click', () => fetchPeers());
137	    btnEditName.addEventListener('click', showEditNameModal);
138	    $('btn-modal-cancel').addEventListener('click', hideEditNameModal);
139	    $('btn-modal-save').addEventListener('click', saveName);
140	    modalNameInput.addEventListener('keydown', (e) => {
141	        if (e.key === 'Enter') saveName();
142	    });
143	    btnSend.addEventListener('click', sendCurrentMessage);
144	    msgInput.addEventListener('keydown', (e) => {
145	        if (e.key === 'Enter') sendCurrentMessage();
146	    });
147	    btnSendFile.addEventListener('click', () => fileInput.click());
148	    fileInput.addEventListener('change', onFileSelected);
149	    btnCloseChat.addEventListener('click', closeCurrentChat);
150	    btnDisconnect.addEventListener('click', disconnectCurrentChat);
151	    btnChatConnect.addEventListener('click', () => {
152	        if (!currentChat) return;
153	        const peer = onlinePeers.get(currentChat) || contacts.get(currentChat);
154	        if (peer) connectToPeer(currentChat, peer.name, peer.ip);
155	    });
156	    btnDeleteContact.addEventListener('click', deleteCurrentContact);
157	
158	    // 手动连接：toggle 展开/收起
159	    const btnManualConnect = $('btn-manual-connect');
160	    const manualIpInput = $('manual-ip-input');
161	
162	    btnManualConnect.addEventListener('click', () => {
163	        const raw = manualIpInput.value.trim();
164	        if (!raw) return;
165	        let [ip, port] = raw.split(':');
166	        port = parseInt(port) || 50002;
167	        connectByIp(ip, port);
168	        manualIpInput.value = '';
169	        toggleManualConnect(); // 收起
170	    });
171	    manualIpInput.addEventListener('keydown', (e) => {
172	        if (e.key === 'Enter') btnManualConnect.click();
173	    });
174	
175	    // 文件续传按钮（事件委托）
176	    chatMessages.addEventListener('click', (e) => {
177	        const btn = e.target.closest('.btn-retry-file');
178	        if (btn) {
179	            const transferId = btn.dataset.transferId;
180	            if (transferId) retryFileTransfer(transferId);
181	        }
182	    });
183	}
184	
185	/** 展开/收起手动连接输入行（内联 onclick 和 JS 均可调用） */
186	function toggleManualConnect() {
187	    const row = $('manual-connect-row');
188	    const btn = $('btn-toggle-manual');
189	    if (!row || !btn) return;
190	    const visible = row.style.display !== 'none';
191	    row.style.display = visible ? 'none' : '';
192	    btn.textContent = visible ? '➕' : '✖';
193	    if (!visible) $('manual-ip-input').focus();
194	}
195	
196	// ===== 定时轮询 =====
197	function startPolling() {
198	    setInterval(fetchPeers, 3000);
199	    setInterval(fetchContacts, 5000);
200	    fetchPeers();
201	    fetchContacts();
202	}
203	
204	async function fetchPeers() {
205	    try {
206	        const resp = await fetch('/api/peers');
207	        const peers = await resp.json();
208	        updateOnlinePeers(peers);
209	    } catch (e) { /* ignore */ }
210	}
211	
212	async function fetchContacts() {
213	    try {
214	        const resp = await fetch('/api/contacts');
215	        const list = await resp.json();
216	        updateContacts(list);
217	    } catch (e) { /* ignore */ }
218	}
219	
220	// ===== 控制消息处理 =====
221	function handleControlMessage(msg) {
222	    const handlers = {
223	        init: handleInit,
224	        peer_online: handlePeerOnline,
225	        peer_offline: handlePeerOffline,
226	        incoming_connection: handleIncomingConnection,
227	        pending_update: handlePendingUpdate,
228	        connection_established: handleConnectionEstablished,
229	        peer_disconnected: handlePeerDisconnected,
230	        disconnected: handleDisconnected,
231	        contact_deleted: handleContactDeleted,
232	        contact_untrusted: handleContactUntrusted,
233	        connection_timeout: handleConnectionTimeout,
234	        connection_idle_close: handleConnectionIdleClose,
235	        chat_message: handleIncomingMessage,
236	        message_ack: handleMessageAck,
237	        send_failed: handleSendFailed,
238	        incoming_file_request: handleIncomingFileRequest,
239	        file_request_response: handleFileRequestResponseFromControl,
240	        forward_file_response: handleForwardFileResponse,
241	        transfer_progress: handleTransferProgress,
242	        transfer_complete: handleTransferComplete,
243	        transfer_cancelled: handleTransferCancelled,
244	        transfer_resumed: handleTransferResumed,
245	    };
246	    const handler = handlers[msg.type];
247	    if (handler) handler(msg);
248	}
249	
250	function handleInit(msg) {
251	    myInfo = msg;
252	    $('my-name-label').textContent = msg.name;
253	    $('my-ip-label').textContent = `IP: ${msg.ip}`;
254	    $('my-network-label').textContent = `网段: ${msg.network}`;
255	    // msg.token 是自己的 token，建立连接时需出示给对方后端验证
256	
257	    // 步骤1：先用 init 消息中的在线节点填充 onlinePeers（不等轮询）
258	    if (msg.online_peers && msg.online_peers.length > 0) {
259	        updateOnlinePeers(msg.online_peers);
260	    }
261	
262	    // 步骤2：加载历史联系人（此时 onlinePeers 已有数据，渲染时状态正确）
263	    if (msg.contacts && msg.contacts.length > 0) {
264	        updateContacts(msg.contacts);
265	    }
266	
267	    // 步骤3：自动重连刷新前已建立的连接（双重来源）
268	    //   来源A — sessionStorage：本浏览器侧记忆，刷新不丢失
269	    //   来源B — active_peers：后端记录，对端浏览器仍连着本后端的 chat WS
270	    const toReconnect = new Set();
271	    for (const uuid of getStoredConnectedPeers()) {
272	        toReconnect.add(uuid);
273	    }
274	    if (msg.active_peers && msg.active_peers.length > 0) {
275	        for (const uuid of msg.active_peers) {
276	            toReconnect.add(uuid);
277	        }
278	    }
279	    for (const peerUuid of toReconnect) {
280	        autoReconnect(peerUuid);
281	    }
282	}
283	
284	function handlePeerOnline(msg) {
285	    // 过滤自己
286	    if (msg.uuid === myInfo.uuid) return;
287	    onlinePeers.set(msg.uuid, { name: msg.name, ip: msg.ip, ws_port: msg.ws_port, token: msg.token });
288	    // 如果历史联系人里有，同步更新在线状态、昵称和 IP（对方可能换了 IP 或改了昵称）
289	    if (contacts.has(msg.uuid)) {
290	        contacts.get(msg.uuid).status = 'online';
291	        if (msg.name) contacts.get(msg.uuid).name = msg.name;
292	        if (msg.ip) contacts.get(msg.uuid).ip = msg.ip;
293	    }
294	    renderOnlineList();
295	    renderContactsList();
296	    updateChatHeaderStatus();
297	}
298	
299	function handlePeerOffline(msg) {
300	    onlinePeers.delete(msg.uuid);
301	    if (contacts.has(msg.uuid)) {
302	        contacts.get(msg.uuid).status = 'offline';
303	    }
304	    // 对应聊天 WS 断开
305	    const ws = activeChats.get(msg.uuid);
306	    if (ws) {
307	        ws.close();
308	        activeChats.delete(msg.uuid);
309	    }
310	    renderOnlineList();
311	    renderContactsList();
312	    updateChatHeaderStatus();
313	    addSystemMessage(msg.uuid, `${msg.name} 已下线`);
314	}
315	
316	function handleIncomingConnection(msg) {
317	    // 保存连接请求信息，包括 IP 和端口，以便同意后反向建立连接
318	    pendingRequests.set(msg.uuid, { name: msg.name, ip: msg.ip, ws_port: msg.ws_port });
319	    renderPendingList();
320	}
321	
322	function handlePendingUpdate(msg) {
323	    // count 可能在 pending 列表被其他地方修改后推送
324	    if (msg.count === 0) pendingRequests.clear();
325	}
326	
327	function handleConnectionEstablished(msg) {
328	    pendingRequests.delete(msg.uuid);
329	    connectedPeers.add(msg.uuid);  // 接收方也标记为已连接
330	    markConnected(msg.uuid);
331	    // 只在 contacts 中不存在时才新建，否则保留已有消息（避免覆盖聊天记录）
332	    if (!contacts.has(msg.uuid)) {
333	        contacts.set(msg.uuid, {
334	            name: msg.name,
335	            ip: msg.ip,
336	            status: 'online',
337	            messages: [],
338	        });
339	    } else {
340	        const c = contacts.get(msg.uuid);
341	        c.name = msg.name;
342	        c.ip = msg.ip;
343	        c.status = 'online';
344	    }
345	    renderPendingList();
346	    renderOnlineList();
347	    renderContactsList();
348	    updateChatHeaderStatus();
349	    // 如果正在等对方的确认（主动发起方），打开聊天
350	    if (currentChat === msg.uuid || !currentChat) {
351	        openChat(msg.uuid);
352	    }
353	}
354	
355	function handlePeerDisconnected(msg) {
356	    activeChats.delete(msg.uuid);
357	    connectedPeers.delete(msg.uuid);
358	    markDisconnected(msg.uuid);
359	    pendingRequests.delete(msg.uuid);
360	    // 中止与该对端的所有进行中文件上传
361	    abortTransfersForPeer(msg.uuid);
362	    renderPendingList();
363	    renderOnlineList();
364	    renderContactsList();
365	    if (currentChat === msg.uuid) {
366	        updateChatHeaderStatus();
367	        addSystemMessage(msg.uuid, `${msg.name || '对方'} 已断开连接`);
368	    }
369	}
370	
371	/** 自己主动断开后的确认回调（后端关闭对端 WS 后返回） */
372	function handleDisconnected(msg) {
373	    activeChats.delete(msg.uuid);
374	    connectedPeers.delete(msg.uuid);
375	    markDisconnected(msg.uuid);
376	    renderOnlineList();
377	    renderContactsList();
378	    if (currentChat === msg.uuid) {
379	        updateChatHeaderStatus();
380	        addSystemMessage(msg.uuid, '你已断开连接');
381	    }
382	}
383	
384	/** 后端确认联系人已删除 → 清理前端关联状态（本端删除） */
385	function handleContactDeleted(msg) {
386	    const uuid = msg.uuid;
387	    activeChats.delete(uuid);
388	    connectedPeers.delete(uuid);
389	    markDisconnected(uuid);
390	    pendingRequests.delete(uuid);
391	    contacts.delete(uuid);
392	    // 清理进行中的文件传输
393	    abortTransfersForPeer(uuid);
394	    for (const [tid, t] of Object.entries(pendingFileTransfers)) {
395	        if (t.uuid === uuid) delete pendingFileTransfers[tid];
396	    }
397	    renderOnlineList();
398	    renderContactsList();
399	    renderPendingList();
400	    if (currentChat === uuid) {
401	        closeCurrentChat();
402	    }
403	}
404	
405	/** 对端删除了我们 → 标记为不可信（保留历史，断开连接） */
406	function handleContactUntrusted(msg) {
407	    const uuid = msg.uuid;
408	    // 断开连接但保留联系人数据
409	    const chatWs = activeChats.get(uuid);
410	    if (chatWs) {
411	        try { chatWs.close(); } catch (e) { /* ignore */ }
412	    }
413	    activeChats.delete(uuid);
414	    connectedPeers.delete(uuid);
415	    markDisconnected(uuid);
416	    pendingRequests.delete(uuid);
417	    // 标记本地 contacts 中的 trusted=false（重新渲染时显示状态）
418	    const contact = contacts.get(uuid);
419	    if (contact) {
420	        contact.trusted = false;
421	    }
422	    // 中止进行中的文件传输
423	    abortTransfersForPeer(uuid);
424	    for (const [tid, t] of Object.entries(pendingFileTransfers)) {
425	        if (t.uuid === uuid) delete pendingFileTransfers[tid];
426	    }
427	    renderOnlineList();
428	    renderContactsList();
429	    renderPendingList();
430	    if (currentChat === uuid) {
431	        updateChatHeaderStatus();
432	    }
433	}
434	
435	/** 连接请求超时（1分钟内用户未操作）→ 清理待处理请求 */
436	function handleConnectionTimeout(msg) {
437	    pendingRequests.delete(msg.uuid);
438	    renderPendingList();
439	    showToast(`${msg.name || '对方'} 的连接请求已超时取消`);
440	}
441	
442	/** 空闲超时关闭（10分钟无消息且无文件传输）→ 清理连接状态 */
443	function handleConnectionIdleClose(msg) {
444	    const uuid = msg.uuid;
445	    activeChats.delete(uuid);
446	    connectedPeers.delete(uuid);
447	    abortTransfersForPeer(uuid);
448	    markDisconnected(uuid);
449	    renderOnlineList();
450	    renderContactsList();
451	    if (currentChat === uuid) {
452	        updateChatHeaderStatus();
453	        addSystemMessage(uuid, '连接因长时间无活动已自动关闭');
454	    }
455	    showToast(`${msg.name || '对方'} 连接已因空闲超时关闭`);
456	}
457	
458	function handleIncomingMessage(msg) {
459	    const uuid = msg.from;
460	    // 保存消息到联系人内存
461	    if (!contacts.has(uuid)) {
462	        contacts.set(uuid, { name: msg.from_name, ip: '', status: 'online', messages: [] });
463	    }
464	    const contact = contacts.get(uuid);
465	    contact.messages.push({
466	        from: uuid,
467	        content: msg.content,
468	        msg_id: msg.msg_id,
469	        timestamp: msg.timestamp,
470	    });
471	    // 立即通知后端持久化到 contacts.json（与后端 _relay_from_peer 形成双保险，
472	    // storage.append_message 内部有 msg_id 去重，重复调用安全）
473	    controlWs.send(JSON.stringify({
474	        type: 'save_message',
475	        peer_uuid: uuid,
476	        sender: uuid,
477	        content: msg.content,
478	        msg_id: msg.msg_id,
479	    }));
480	    if (currentChat === uuid) {
481	        renderMessages(uuid);
482	    }
483	    // 当前没有聊天窗口时，自动打开
484	    if (!currentChat) {
485	        openChat(uuid);
486	    }
487	    renderContactsList();
488	}
489	
490	function handleMessageAck(msg) {
491	    pendingMessages.delete(msg.msg_id);
492	    if (currentChat) renderMessages(currentChat);
493	}
494	
495	function handleSendFailed(msg) {
496	    // 标记消息发送失败
497	    const pending = pendingMessages.get(msg.msg_id);
498	    if (pending) {
499	        pending.status = 'failed';
500	        pendingMessages.set(msg.msg_id, pending);
501	    }
502	    if (currentChat) renderMessages(currentChat);
503	}
504	
505	// ===== 文件传输消息处理 =====
506	
507	function handleIncomingFileRequest(msg) {
508	    // 续传：自动接受，不弹窗
509	    if (msg.resume) {
510	        autoAcceptResumeTransfer(msg);
511	        return;
512	    }
513	    showFileRequestModal(msg);
514	}
515	
516	/** 续传自动接受（不弹窗），更新已有文件气泡或插入新气泡 */
517	function autoAcceptResumeTransfer(msg) {
518	    // 发送接受响应
519	    controlWs.send(JSON.stringify({
520	        type: 'file_response',
521	        transfer_id: msg.transfer_id,
522	        accepted: true,
523	    }));
524	
525	    const uuid = msg.from_uuid;
526	    if (!contacts.has(uuid)) {
527	        contacts.set(uuid, { name: msg.from_name, ip: '', status: 'online', messages: [] });
528	    }
529	    const contact = contacts.get(uuid);
530	    const msgId = 'f_' + msg.transfer_id;
531	    const existingIdx = contact.messages.findIndex(m => m.msg_id === msgId);
532	    if (existingIdx >= 0) {
533	        // 续传：更新已有消息，保留旧进度（不重置为0）
534	        contact.messages[existingIdx].status = 'downloading';
535	        // progress 保持中断前的值，后续由 transfer_progress 更新
536	        saveFileMessage(uuid, contact.messages[existingIdx]);
537	    } else {
538	        const fileMsg = {
539	            from: uuid,
540	            type: 'file',
541	            msg_id: msgId,
542	            timestamp: new Date().toISOString(),
543	            file_name: msg.file_name,
544	            file_size: msg.file_size,
545	            transfer_id: msg.transfer_id,
546	            direction: 'receive',
547	            status: 'downloading',
548	            progress: 0,
549	        };
550	        contact.messages.push(fileMsg);
551	        saveFileMessage(uuid, fileMsg);
552	    }
553	    if (currentChat === uuid) {
554	        renderMessages(uuid);
555	    } else {
556	        openChat(uuid);
557	    }
558	}
559	
560	/**
561	 * 处理来自控制 WS 的文件请求响应（通过后端 _relay_from_peer 转发的）。
562	 * 与来自聊天 WS 直连的响应统一走 handleFileRequestResponse。
563	 */
564	function handleFileRequestResponseFromControl(msg) {
565	    handleFileRequestResponse(msg);
566	}
567	
568	/**
569	 * 统一处理文件请求响应。
570	 * 发送方会从聊天 WS 直连或控制 WS 两条路径收到此消息，
571	 * 通过 transfer_id 精确匹配，且幂等（started 标记防止重复启动上传）。
572	 */
573	function handleFileRequestResponse(msg) {
574	    const transferId = msg.transfer_id;
575	    const t = pendingFileTransfers[transferId];
576	    if (!t) return; // 不是我们的传输
577	
578	    if (msg.accepted) {
