1813	
1814	    const CHUNK_SIZE = 64 * 1024; // 64KB
1815	    const transferId = 't_' + myInfo.uuid + '_' + Date.now();
1816	    const totalChunks = Math.ceil(file.size / CHUNK_SIZE);
