1874	/**
1875	 * 开始分片上传文件到对方后端。
1876	 * 每发送一个分片后更新聊天气泡中的进度。
1877	 */
1878	async function startChunkUpload(transferId) {
1879	    const t = pendingFileTransfers[transferId];
1880	    if (!t) return;
1881	
1882	    const result = findFileMsgByTransferId(transferId);
1883	    const fileMsg = result ? result.msg : null;
1884	    if (result) {
1885	        fileMsg.status = 'uploading';
1886	        saveFileMessage(t.uuid, fileMsg);
1887	        if (currentChat === t.uuid) renderMessages(t.uuid);
1888	    }
1889	
1890	    const peer = onlinePeers.get(t.uuid);
1891	    if (!peer) {
1892	        showToast('对方不在线，无法发送文件');
1893	        if (fileMsg) {
1894	            fileMsg.status = 'failed';
1895	            saveFileMessage(t.uuid, fileMsg);
1896	            if (currentChat === t.uuid) renderMessages(t.uuid);
1897	        }
1898	        delete pendingFileTransfers[transferId];
1899	        return;
1900	    }
1901	
1902	    const file = t.file;
1903	    const CHUNK_SIZE = t.CHUNK_SIZE;
1904	    const totalChunks = t.totalChunks;
1905	    const peerPort = peer.ws_port || 50002;
1906	
1907	    for (let i = t.currentChunk; i < totalChunks; i++) {
1908	        // 检查连接是否被中断（断开连接 / 对方下线）
1909	        if (t.aborted) {
1910	            if (fileMsg) {
1911	                fileMsg.status = 'cancelled';
1912	                saveFileMessage(t.uuid, fileMsg);
1913	                if (currentChat === t.uuid) renderMessages(t.uuid);
1914	            }
1915	            return; // 连接中断，中止上传
1916	        }
1917	
1918	        const start = i * CHUNK_SIZE;
1919	        const end = Math.min(start + CHUNK_SIZE, file.size);
1920	        const blob = file.slice(start, end);
1921	
1922	        let dataB64;
1923	        try {
1924	            dataB64 = await readAsBase64(blob);
1925	        } catch (e) {
1926	            // 文件读取失败（权限变更、文件被删、磁盘错误等），不可恢复
1927	            t.failed = true;
1928	            if (fileMsg) {
1929	                fileMsg.status = 'failed';
1930	                saveFileMessage(t.uuid, fileMsg);
1931	                if (currentChat === t.uuid) renderMessages(t.uuid);
1932	            }
1933	            return;
1934	        }
1935	
1936	        let retries = 0;
1937	        let success = false;
1938	
1939	        while (retries < 3 && !success) {
1940	            try {
1941	                const resp = await fetch(`http://${peer.ip}:${peerPort}/api/transfer/chunk`, {
1942	                    method: 'POST',
1943	                    headers: { 'Content-Type': 'application/json' },
1944	                    body: JSON.stringify({
1945	                        transfer_id: transferId,
1946	                        chunk_index: i,
1947	                        data: dataB64,
1948	                    }),
1949	                });
1950	                if (resp.ok) {
1951	                    success = true;
1952	                    t.currentChunk = i + 1;
1953	                    // 更新进度条
1954	                    if (fileMsg) {
1955	                        fileMsg.progress = Math.round((i + 1) / totalChunks * 100);
1956	                        if (currentChat === t.uuid) renderMessages(t.uuid);
1957	                    }
1958	                } else {
1959	                    retries++;
1960	                }
1961	            } catch (e) {
1962	                retries++;
1963	            }
1964	        }
1965	
1966	        if (!success) {
1967	            t.failed = true;
1968	            if (fileMsg) {
1969	                fileMsg.status = 'failed';
1970	                saveFileMessage(t.uuid, fileMsg);
1971	                if (currentChat === t.uuid) renderMessages(t.uuid);
1972	            }
1973	            return; // 传输中断（保留 t 以便续传）
1974	        }
1975	    }
1976	
1977	    // 所有分片发送完毕 → 通知对方合并
1978	    try {
1979	        await fetch(`http://${peer.ip}:${peerPort}/api/transfer/complete`, {
1980	            method: 'POST',
1981	            headers: { 'Content-Type': 'application/json' },
1982	            body: JSON.stringify({ transfer_id: transferId }),
1983	        });
1984	        if (fileMsg) {
1985	            fileMsg.status = 'complete';
1986	            fileMsg.progress = 100;
1987	            saveFileMessage(t.uuid, fileMsg);
1988	            if (currentChat === t.uuid) renderMessages(t.uuid);
1989	        }
1990	    } catch (e) {
1991	        if (fileMsg) {
1992	            fileMsg.status = 'failed';
1993	            saveFileMessage(t.uuid, fileMsg);
1994	            if (currentChat === t.uuid) renderMessages(t.uuid);
1995	        }
1996	    }
1997	
1998	    delete pendingFileTransfers[transferId];
1999	}
