2001	/**
2002	 * 重新发送（续传）失败的文件。查询接收方已收分片，只补发缺失部分。
2003	 * @param {string} transferId - 原传输 ID
2004	 */
2005	async function retryFileTransfer(transferId) {
2006	    // 1. 检查是否有文件数据（页面刷新后 File 对象会丢失）
2007	    const t = pendingFileTransfers[transferId];
2008	    if (!t || !t.file) {
2009	        showToast('无法续传：文件数据已丢失，请重新选择文件发送');
2010	        return;
2011	    }
2012	
2013	    // 2. 检查对方是否在线
2014	    const peer = onlinePeers.get(t.uuid);
2015	    if (!peer) {
2016	        showCenterToast('对方当前不在线，等待对方上线后才能重传嗷~');
2017	        return;
2018	    }
2019	
2020	    // 2.5 必须有已建立的 chat WS 连接才能续传（否则 file_request 无法送达）
2021	    const chatWs = activeChats.get(t.uuid);
2022	    const isConnected = (chatWs && chatWs.readyState === WebSocket.OPEN) || connectedPeers.has(t.uuid);
2023	    if (!isConnected) {
2024	        showCenterToast('连接按钮都懒得点，那就别想重传文件~');
2025	        return;
2026	    }
2027	
2028	    // 3. 查询接收方已收到的分片数
2029	    let receivedChunks = 0;
2030	    const peerPort = peer.ws_port || 50002;
2031	    try {
2032	        const resp = await fetch(`http://${peer.ip}:${peerPort}/api/transfer/status/${transferId}`);
2033	        if (resp.ok) {
2034	            const status = await resp.json();
2035	            receivedChunks = status.received_chunks_count || 0;
2036	        }
2037	    } catch (e) {
2038	        // 进度丢失，从头开始
2039	        console.log('[Retry] 无法获取进度，从头开始:', e.message);
2040	    }
2041	
2042	    // 4. 更新传输状态 — 从已收到的下一片开始
2043	    t.currentChunk = receivedChunks;
2044	    t.started = false;
2045	    t.failed = false;
2046	    t.aborted = false;
2047	
2048	    // 5. 更新文件消息气泡
2049	    const result = findFileMsgByTransferId(transferId);
2050	    if (result) {
2051	        result.msg.status = 'waiting';
2052	        result.msg.progress = Math.round(receivedChunks / t.totalChunks * 100);
2053	        saveFileMessage(t.uuid, result.msg);
2054	        if (currentChat === t.uuid) renderMessages(t.uuid);
2055	    }
2056	
2057	    // 6. 重新发送 file_request（带 resume 标记，接收方会跳过确认直接接受）
2058	    const fileRequestMsg = {
2059	        transfer_id: transferId,
2060	        file_name: t.file.name,
2061	        file_size: t.file.size,
2062	        chunk_size: t.CHUNK_SIZE,
2063	        total_chunks: t.totalChunks,
2064	        resume: true,
2065	    };
2066	
2067	    const ws = activeChats.get(t.uuid);
2068	    if (ws && ws.readyState === WebSocket.OPEN) {
2069	        ws.send(JSON.stringify({ type: 'file_request', ...fileRequestMsg }));
2070	    } else {
2071	        // 回退路径：通过 control WS 转发
2072	        controlWs.send(JSON.stringify({
2073	            type: 'file_request',
2074	            to_uuid: t.uuid,
2075	            ...fileRequestMsg,
2076	        }));
2077	    }
2078	}
