2080	function readAsBase64(blob) {
2081	    return new Promise((resolve, reject) => {
2082	        const reader = new FileReader();
2083	        reader.onloadend = () => {
2084	            const result = reader.result;
2085	            // 去掉 "data:...;base64," 前缀
2086	            const b64 = result.split(',')[1] || result;
2087	            resolve(b64);
2088	        };
2089	        reader.onerror = () => {
2090	            reject(new Error('文件读取失败'));
2091	        };
2092	        reader.readAsDataURL(blob);
2093	    });
2094	}
